1	// FlashAttention-2-style BF16 forward kernel for sm_86 (RTX 3090 Ti).
2	// - wmma 16x16x16 tensor-core matmuls (mma.sync.m16n8k16 under the hood)
3	// - cp.async single-buffered K/V tiles (39,936 B smem -> 2 blocks/SM on sm_86,
4	//   which doubles warps-in-flight vs a 96 KB double-buffered layout);
5	//   padded row stride (136 bf16) makes ldmatrix reads conflict-free
6	// - online softmax; softmaxed scores are staged as bf16 through a small
7	//   per-warp shared tile (true row/col layout) before the PV matmul, because
8	//   the m16n16k16 accumulator layout differs from the matrix_a layout.
9	#include <torch/extension.h>
10	#include <ATen/cuda/CUDAContext.h>
11	#include <c10/cuda/CUDAGuard.h>
12	#include <cuda_bf16.h>
13	#include <mma.h>
14	#include <math.h>
15	
16	namespace {
17	
18	using namespace nvcuda;
19	
20	constexpr int BLOCK_M = 64;    // query rows per block
21	constexpr int BLOCK_N = 16;    // kv rows per tile
22	constexpr int HEAD_DIM = 128;
23	constexpr int NUM_WARPS = 4;
24	constexpr int NUM_THREADS = NUM_WARPS * 32;
25	constexpr int PADDED_D = HEAD_DIM + 8;        // 16 B/row padding (K/V tiles)
26	constexpr int PADDED_Q = HEAD_DIM + 8;        // Q/O buffer stride == PADDED_D
27	constexpr int TILE_ELEMS = BLOCK_N * PADDED_D;  // per K or V tile (bf16)
28	constexpr int O_ELEMS = BLOCK_M * PADDED_Q;     // O staging (reuses Q buffer)
29	// Single-buffered K/V (2 tiles) + compact Q/O buffer keeps smem at 25,600 B
30	// -> 4 blocks/SM on sm_86 (16 warps vs 12) on this latency-bound kernel.
31	// P is fed to the PV matmul directly from registers (wmma m16n16k16 matrix_a
32	// row_major layout == accumulator layout), no smem round-trip.
33	constexpr int SMEM_BYTES = 2 * TILE_ELEMS * 2 + O_ELEMS * 2;  // 25,600 B
34	
35	__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
36	    uint32_t s = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
37	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem));
38	}
39	__device__ __forceinline__ void cp_async_commit() {
40	    asm volatile("cp.async.commit_group;\n");
41	}
42	template<int N>
43	__device__ __forceinline__ void cp_async_wait() {
44	    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
45	}
46	
47	// Copy an nrows x HEAD_DIM tile from gmem (rows row0..) to padded shared,
48	// zero-filling rows past seq_len. Used for K/V tiles (nrows = BLOCK_N) and
49	// to stage Q (nrows = BLOCK_M).
50	__device__ __forceinline__ void load_tile(
51	    const __nv_bfloat16* __restrict__ src, __nv_bfloat16* __restrict__ dst,
52	    int row0, int seq_len, int nrows, int pitch)
53	{
54	    const int CHUNKS = nrows * HEAD_DIM / 8;  // 16B chunks
55	#pragma unroll
56	    for (int i = threadIdx.x; i < CHUNKS; i += NUM_THREADS) {
57	        const int row = i / (HEAD_DIM / 8);
58	        const int col8 = i % (HEAD_DIM / 8);
59	        const int grow = row0 + row;
60	        __nv_bfloat16* s = dst + row * pitch + col8 * 8;
61	        if (grow < seq_len) {
62	            cp_async16(s, src + (long long)grow * HEAD_DIM + col8 * 8);
63	        } else {
64	            *reinterpret_cast<uint4*>(s) = make_uint4(0, 0, 0, 0);
65	        }
66	    }
67	}
68	
69	__device__ __forceinline__ float warp_max4(float v) {
70	#pragma unroll
71	    for (int off = 1; off < 4; off <<= 1)
72	        v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, off));
73	    return v;
74	}
75	__device__ __forceinline__ float warp_sum4(float v) {
76	#pragma unroll
77	    for (int off = 1; off < 4; off <<= 1)
78	        v += __shfl_xor_sync(0xffffffffu, v, off);
79	    return v;
80	}
81	
82	__global__ void __launch_bounds__(NUM_THREADS, 3)
83	attention_fwd_kernel(const __nv_bfloat16* __restrict__ q,
84	                     const __nv_bfloat16* __restrict__ k,
85	                     const __nv_bfloat16* __restrict__ v,
86	                     __nv_bfloat16* __restrict__ out,
87	                     int seq_len, float scale, bool causal,
88	                     int num_head

